import { Search, X } from '@hexa-ui/icons';
import React from 'react';
import { IconButton } from '../../../icon-button';
import { IconButtonsContainer } from './IconButtons.styles';

interface IconButtonsProps {
  handleOnClean: (event: React.MouseEvent<HTMLButtonElement>) => void;
  handleOnPreview?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  elevation?: boolean;
  shouldShowPreviewButton: boolean;
}

export const IconButtons = ({
  handleOnClean,
  handleOnPreview,
  elevation = false,
  shouldShowPreviewButton,
}: IconButtonsProps) => (
  <IconButtonsContainer>
    {shouldShowPreviewButton && (
      <IconButton
        data-testid="preview-button"
        type="button"
        variant="secondary"
        size="small"
        icon={Search}
        onClick={handleOnPreview}
        elevation={elevation}
        aria-label="Preview"
      />
    )}

    <IconButton
      data-testid="clean-button"
      type="button"
      variant="secondary"
      size="small"
      icon={X}
      onClick={handleOnClean}
      elevation={elevation}
      aria-label="Delete and clear"
    />
  </IconButtonsContainer>
);
